css:
/* Learning by Doing — Executive-education / academy theme: warm parchment, ink, scholarly teal-green. Light, editorial, distinct from dark sims. */
.lbd-sim-container {
    padding: 28px;
    background: #f4f1ea;
    background-image: linear-gradient(180deg, #f7f4ee 0%, #efe9df 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2b2a26;
}
.lbd-sim-header {
    background: linear-gradient(135deg, #14342b 0%, #1f4a3c 100%);
    color: #f3efe6;
    padding: 32px 36px;
    border-radius: 8px;
    margin-bottom: 24px;
    border-left: 6px solid #c8a24a;
    box-shadow: 0 10px 28px rgba(20,52,43,0.22);
    position: relative;
    overflow: hidden;
}
.lbd-sim-header::after {
    content: "";
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(135deg, rgba(200,162,74,0.06) 0 14px, transparent 14px 28px);
    pointer-events: none;
}
.lbd-sim-header-tag {
    display: inline-block;
    background: rgba(200,162,74,0.2);
    color: #e9cf90;
    padding: 4px 12px;
    border-radius: 4px;
    font-size: 0.74rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    margin-bottom: 12px;
    font-weight: 700;
    position: relative;
}
.lbd-sim-header h1 {
    font-size: 2.1rem;
    font-weight: 800;
    margin: 0 0 10px 0;
    letter-spacing: -0.01em;
    position: relative;
    font-family: Georgia, 'Times New Roman', serif;
}
.lbd-sim-subtitle {
    margin: 0;
    font-size: 1.02rem;
    color: #d6e0d6;
    max-width: 780px;
    line-height: 1.55;
    position: relative;
}
.lbd-sim-period-counter {
    background: #ffffff;
    border: 1px solid #ddd5c6;
    border-radius: 8px;
    padding: 14px 22px;
    margin-bottom: 24px;
    font-size: 0.95rem;
    color: #6b6557;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    box-shadow: 0 2px 8px rgba(20,52,43,0.05);
}
.lbd-sim-period-counter span {
    font-weight: 700;
    color: #2b2a26;
}
.lbd-sim-round-name {
    margin-left: 14px;
    color: #1f4a3c;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.85rem;
}
.lbd-sim-clock {
    margin-left: auto;
    color: #9a7a1f !important;
    font-variant-numeric: tabular-nums;
    background: rgba(200,162,74,0.16);
    padding: 4px 12px;
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 700;
}
.lbd-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.lbd-sim-status-card {
    background: #ffffff;
    border: 1px solid #e0d8c9;
    border-radius: 8px;
    padding: 22px 20px;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    box-shadow: 0 3px 10px rgba(20,52,43,0.06);
}
.lbd-sim-status-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 22px rgba(20,52,43,0.12);
}
.lbd-sim-card-primary {
    border-top: 4px solid #1f4a3c;
    background: linear-gradient(180deg, #f0f6f1 0%, #ffffff 100%);
}
.lbd-sim-card-time {
    border-top: 4px solid #c8a24a;
    background: linear-gradient(180deg, #fbf6ea 0%, #ffffff 100%);
}
.lbd-sim-label {
    color: #8a8474;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    margin-bottom: 10px;
}
.lbd-sim-value {
    font-size: 2.5rem;
    font-weight: 800;
    color: #2b2a26;
    line-height: 1;
    margin-bottom: 6px;
    font-variant-numeric: tabular-nums;
}
.lbd-sim-card-primary .lbd-sim-value {
    color: #1f4a3c;
}
.lbd-sim-card-time .lbd-sim-value {
    color: #9a7a1f;
}
.lbd-sim-sublabel {
    color: #908a7a;
    font-size: 0.78rem;
}
.lbd-sim-briefing {
    background: #ffffff;
    border: 1px solid #e5dcc8;
    border-left: 5px solid #c8a24a;
    border-radius: 8px;
    padding: 22px 24px;
    margin-bottom: 24px;
    display: flex;
    gap: 18px;
    align-items: flex-start;
    box-shadow: 0 3px 10px rgba(20,52,43,0.06);
}
.lbd-sim-briefing-icon {
    font-size: 2rem;
    line-height: 1;
    flex-shrink: 0;
}
.lbd-sim-briefing-body {
    flex: 1;
}
.lbd-sim-briefing-title {
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f4a3c;
    margin-bottom: 8px;
    font-family: Georgia, 'Times New Roman', serif;
}
.lbd-sim-briefing-text {
    color: #463f33;
    line-height: 1.65;
    font-size: 0.96rem;
}
.lbd-sim-briefing-text strong {
    color: #1f4a3c;
}
.lbd-sim-controls {
    background: #ffffff;
    border: 1px solid #e0d8c9;
    border-radius: 8px;
    padding: 26px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(20,52,43,0.06);
}
.lbd-sim-controls h3 {
    font-size: 1.12rem;
    font-weight: 800;
    color: #2b2a26;
    margin: 0 0 18px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid #e5dcc8;
    font-family: Georgia, 'Times New Roman', serif;
}
.lbd-sim-panel {
    margin-bottom: 8px;
}
.lbd-sim-controls label {
    display: block;
    font-size: 0.85rem;
    font-weight: 600;
    color: #4a463b;
    margin-bottom: 6px;
    margin-top: 16px;
}
.lbd-sim-controls input[type="number"],
.lbd-sim-controls input[type="text"],
.lbd-sim-controls select {
    width: 100%;
    background-color: #fbf9f4;
    border: 1px solid #cfc6b4;
    color: #2b2a26;
    border-radius: 5px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.lbd-sim-controls select option {
    background-color: #ffffff;
    color: #2b2a26;
}
.lbd-sim-controls input[type="number"]:focus,
.lbd-sim-controls input[type="text"]:focus,
.lbd-sim-controls select:focus {
    outline: none;
    border-color: #1f4a3c;
    box-shadow: 0 0 0 3px rgba(31,74,60,0.15);
}
.lbd-sim-controls input[type="range"] {
    width: 100%;
    accent-color: #1f4a3c;
    margin-top: 8px;
}
.lbd-sim-range-readout,
.lbd-sim-split-readout {
    font-size: 0.85rem;
    color: #6b6557;
    margin-top: 6px;
}
.lbd-sim-range-readout span:last-child,
.lbd-sim-split-readout span:nth-child(2) {
    color: #9a7a1f;
    font-weight: 700;
}
.lbd-sim-controls .btn {
    margin-top: 24px;
    padding: 12px 26px;
    border-radius: 5px;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    border: none;
    transition: background 0.2s ease, transform 0.15s ease;
}
.lbd-sim-controls .btn-primary {
    background: #1f4a3c;
    color: #ffffff;
}
.lbd-sim-controls .btn-primary:hover {
    background: #2a6150;
    transform: translateY(-1px);
}
.lbd-sim-controls .btn-outline-secondary {
    background: transparent;
    color: #6b6557;
    border: 1px solid #cfc6b4;
    margin-left: 10px;
}
.lbd-sim-controls .btn-outline-secondary:hover {
    background: #f0ece2;
    color: #2b2a26;
}
.lbd-sim-coach {
    background: linear-gradient(135deg, #14342b 0%, #20493b 100%);
    color: #eef2ea;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
    border-left: 5px solid #c8a24a;
    box-shadow: 0 6px 18px rgba(20,52,43,0.18);
}
.lbd-sim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #e9cf90;
    font-weight: 800;
    margin-bottom: 10px;
}
.lbd-sim-coach-body {
    line-height: 1.65;
    font-size: 0.98rem;
    color: #eef2ea;
}
.lbd-sim-coach-body strong {
    color: #f0d99a;
}
.lbd-sim-history {
    background: #ffffff;
    border: 1px solid #e0d8c9;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
    overflow-x: auto;
    box-shadow: 0 3px 10px rgba(20,52,43,0.06);
}
.lbd-sim-history h3 {
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b2a26;
    margin: 0 0 14px 0;
    font-family: Georgia, 'Times New Roman', serif;
}
.lbd-sim-history table {
    margin-bottom: 0;
    color: #2b2a26;
    width: 100%;
}
.lbd-sim-history table th {
    background: #f0ece2;
    color: #6b6557;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-weight: 700;
    border-bottom: 2px solid #ddd5c6;
    padding: 10px 12px;
}
.lbd-sim-history table td {
    color: #3a352c;
    font-size: 0.9rem;
    padding: 10px 12px;
    border-bottom: 1px solid #ece6da;
}
.lbd-sim-chart {
    background: #ffffff;
    border: 1px solid #e0d8c9;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
    height: 380px;
    box-shadow: 0 3px 10px rgba(20,52,43,0.06);
}
.lbd-sim-chart h3 {
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b2a26;
    margin: 0 0 14px 0;
    font-family: Georgia, 'Times New Roman', serif;
}
.lbd-sim-chart canvas {
    max-height: 300px;
}
@media (max-width: 768px) {
    .lbd-sim-container { padding: 16px; }
    .lbd-sim-header { padding: 24px 22px; }
    .lbd-sim-header h1 { font-size: 1.6rem; }
    .lbd-sim-status-cards { grid-template-columns: repeat(2, 1fr); }
    .lbd-sim-value { font-size: 1.9rem; }
    .lbd-sim-period-counter { flex-wrap: wrap; }
    .lbd-sim-clock { margin-left: 0; width: 100%; margin-top: 6px; text-align: center; }
    .lbd-sim-round-name { margin-left: 0; }
}


/* FIX v1.1.0 — completion / renewal-debrief screen */
.lbd-completion { padding: 10px 6px; text-align: center; }
.lbd-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.lbd-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.lbd-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.lbd-completion-score strong { color: #ca8a04; }
.lbd-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.lbd-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 100px; }
.lbd-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.lbd-completion-metric strong { font-size: 16px; color: #0f172a; }
.lbd-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 680px; text-align: left; }
.lbd-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #fefce8; border-left: 3px solid #ca8a04; border-radius: 4px; color: #1e293b; font-size: 13px; }

