(function() {
    'use strict';

    class LearningByDoingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Learning by Doing`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // The concept's truth: doing+reflecting drives transfer; the debrief is the lesson.
            this.BASELINE = 58;   // current programme tracking
            this.TARGET = 70;     // renewal threshold
            this.CAP = 20;        // immovable active-session minutes
            this.FEE_AT_RISK = 360000; // EUR tied to the transfer score
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    transfer: 58,          // projected transfer score, anchored at baseline
                    engagement: 50,        // cohort-wide engagement (0-100)
                    debriefQuality: 40,    // strength of reflection design (0-100)
                    timeUsed: 20,          // minutes of active time committed (cap = 20)
                    overrun: false,        // exercise blew the cap
                    debriefStarved: false, // reflection cut under 5 min
                    revertedToTelling: false,
                    randomCasting: false,
                    measuredSatisfaction: false,
                    transferHistory: [58],
                    engagementHistory: [50],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    gap: `decisions`,
                    measure: `observed`,
                    objectives: 1,
                    format: `roleplay`,
                    exercise: 12,
                    failmode: `uneven`,
                    decisionSeat: `rotate`,
                    vp: `observer`,
                    trigger: `forced`,
                    pressure: 65,
                    structure: `whatso`,
                    debriefMin: 8,
                    plan: `observed`,
                    cut: `objectives`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const measure = document.getElementById(`measureInput`);
                const obj = document.getElementById(`objectivesInput`);
                if (gap) decisions.gap = gap.value;
                if (measure) decisions.measure = measure.value;
                if (obj) decisions.objectives = parseInt(obj.value, 10);
                if (!Number.isFinite(decisions.objectives) || decisions.objectives < 1 || decisions.objectives > 6) {
                    warn(`warn_objectives_range`); return false;
                }
            } else if (round === 2) {
                const fmt = document.getElementById(`formatInput`);
                const ex = document.getElementById(`exerciseInput`);
                const fail = document.getElementById(`failmodeInput`);
                if (fmt) decisions.format = fmt.value;
                if (fail) decisions.failmode = fail.value;
                if (ex) decisions.exercise = parseInt(ex.value, 10);
                if (!Number.isFinite(decisions.exercise) || decisions.exercise < 2 || decisions.exercise > 20) {
                    warn(`warn_exercise_range`); return false;
                }
            } else if (round === 3) {
                const seat = document.getElementById(`decisionSeatInput`);
                const vp = document.getElementById(`vpInput`);
                const trig = document.getElementById(`triggerInput`);
                const pr = document.getElementById(`pressureInput`);
                if (seat) decisions.decisionSeat = seat.value;
                if (vp) decisions.vp = vp.value;
                if (trig) decisions.trigger = trig.value;
                if (pr) decisions.pressure = parseInt(pr.value, 10);
                if (!Number.isFinite(decisions.pressure) || decisions.pressure < 0 || decisions.pressure > 100) {
                    warn(`warn_pressure_range`); return false;
                }
            } else if (round === 4) {
                const st = document.getElementById(`structureInput`);
                const dm = document.getElementById(`debriefMinInput`);
                const plan = document.getElementById(`planInput`);
                const cut = document.getElementById(`cutInput`);
                if (st) decisions.structure = st.value;
                if (plan) decisions.plan = plan.value;
                if (cut) decisions.cut = cut.value;
                if (dm) decisions.debriefMin = parseInt(dm.value, 10);
                if (!Number.isFinite(decisions.debriefMin) || decisions.debriefMin < 0 || decisions.debriefMin > 18) {
                    warn(`warn_debrief_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let transferDelta = 0, engagementDelta = 0, debriefDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the right gap + define transfer (not satisfaction) + don't over-scope.
                if (d.gap === `decisions`) { transferDelta += 8; engagementDelta += 4; coachKey = `coach_r1_gap_right`; }
                else if (d.gap === `comms`) { transferDelta += 2; coachKey = `coach_r1_gap_comms`; }
                else if (d.gap === `knowledge`) { transferDelta -= 2; coachKey = `coach_r1_gap_knowledge`; }
                else { transferDelta -= 5; coachKey = `coach_r1_gap_vague`; }

                if (d.measure === `observed`) { transferDelta += 6; coachKey = `coach_r1_measure_observed`; }
                else if (d.measure === `manager`) { transferDelta += 4; }
                else if (d.measure === `quiz`) { transferDelta -= 2; }
                else if (d.measure === `satisfaction`) {
                    transferDelta -= 6; ds.measuredSatisfaction = true; coachKey = `coach_r1_measure_satisfaction`;
                }

                // Over-scoping: experiential time is scarce. 1-2 objectives focus; each extra dilutes.
                if (d.objectives <= 2) { transferDelta += 5; coachKey = (d.gap === `decisions`) ? `coach_r1_focused` : coachKey; }
                else { transferDelta -= (d.objectives - 2) * 3; coachKey = `coach_r1_overscope`; }

                summaryKey = (d.gap === `decisions` && d.measure !== `satisfaction` && d.objectives <= 2) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Format trade-off + fitting the exercise in 12 (leaving 8 for debrief) + naming the real risk.
                switch (d.format) {
                    case `roleplay`:
                        engagementDelta += 18; transferDelta += 8; coachKey = `coach_r2_roleplay`; break;
                    case `forum`:
                        engagementDelta += 8; transferDelta += 6; coachKey = `coach_r2_forum`; break;
                    case `computer`:
                        engagementDelta += 12; transferDelta += 7; coachKey = `coach_r2_computer`; break;
                    case `lecture`:
                        // Reverting to telling — fails the transfer mandate (Common Error 1).
                        engagementDelta -= 14; transferDelta -= 10; ds.revertedToTelling = true; coachKey = `coach_r2_lecture`; break;
                }

                // The cap: exercise + debrief must fit 20. Leave ~8 for debrief (exercise ~12).
                ds.timeUsed = d.exercise + (state.decisions.debriefMin || 8);
                if (d.exercise > 12) {
                    // Over-scoped exercise: chaos and/or a gutted debrief (Common Error 2).
                    ds.overrun = true;
                    const over = d.exercise - 12;
                    engagementDelta -= over * 2;   // truncates into chaos
                    transferDelta -= over * 2;
                    coachKey = `coach_r2_overrun`;
                } else if (d.exercise < 8) {
                    transferDelta += 2; // disciplined, leaves room for reflection
                }

                // Naming the real failure mode and mitigating it earns a small design-discipline credit.
                if (d.failmode === `none`) { transferDelta -= 3; coachKey = `coach_r2_norisk`; }
                else if ((d.format === `roleplay` && d.failmode === `uneven`) ||
                         (d.format === `computer` && d.failmode === `tooltrap`)) {
                    transferDelta += 4; engagementDelta += 3;
                }

                summaryKey = (d.format !== `lecture` && d.exercise <= 12) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Cast deliberately so the loud don't dominate and the quiet don't disengage.
                switch (d.decisionSeat) {
                    case `rotate`:
                        engagementDelta += 14; transferDelta += 6; coachKey = `coach_r3_rotate`; break;
                    case `skeptic`:
                        engagementDelta += 16; transferDelta += 5; coachKey = `coach_r3_skeptic`; break;
                    case `vp`:
                        engagementDelta -= 10; transferDelta -= 4; coachKey = `coach_r3_vpseat`; break;
                    case `volunteer`:
                        // Random casting — dominant VP grabs the seat, quiet experts vanish (Common Error 4).
                        engagementDelta -= 16; transferDelta -= 6; ds.randomCasting = true; coachKey = `coach_r3_volunteer`; break;
                }

                if (d.vp === `observer`) { engagementDelta += 8; }
                else if (d.vp === `pair`) { engagementDelta += 10; transferDelta += 3; coachKey = (d.decisionSeat !== `vp`) ? `coach_r3_vppair` : coachKey; }
                else if (d.vp === `lead`) { engagementDelta -= 10; coachKey = `coach_r3_vplead`; }
                else if (d.vp === `ignore`) { engagementDelta -= 8; }

                if (d.trigger === `forced`) { transferDelta += 8; engagementDelta += 5; }
                else if (d.trigger === `open`) { transferDelta -= 6; engagementDelta -= 4; coachKey = `coach_r3_open`; }
                else if (d.trigger === `scripted`) { transferDelta -= 3; }

                // Time pressure: a sweet spot ~65 creates felt decisions without panic.
                const gap = Math.abs(d.pressure - 65);
                if (gap <= 15) { engagementDelta += 4; transferDelta += 3; }
                else if (d.pressure < 35) { engagementDelta -= 4; coachKey = `coach_r3_lowpressure`; }
                else if (d.pressure > 90) { engagementDelta -= 3; }

                summaryKey = (d.decisionSeat !== `volunteer` && d.trigger === `forced` && d.vp !== `lead`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // The debrief is the lesson; protect reflection; measure transfer, not satisfaction; subtract.
                switch (d.structure) {
                    case `whatso`:
                        debriefDelta += 30; transferDelta += 10; coachKey = `coach_r4_whatso`; break;
                    case `kolb`:
                        debriefDelta += 28; transferDelta += 10; coachKey = `coach_r4_kolb`; break;
                    case `recap`:
                        debriefDelta += 4; transferDelta -= 6; coachKey = `coach_r4_recap`; break;
                    case `none`:
                        debriefDelta -= 10; transferDelta -= 12; ds.debriefStarved = true; coachKey = `coach_r4_nodebrief`; break;
                }

                // Protected minutes: under 5 min starves the debrief (Common Error 3) regardless of structure.
                if (d.debriefMin < 5) {
                    ds.debriefStarved = true;
                    debriefDelta -= 18;
                    transferDelta -= 8;
                    coachKey = `coach_r4_starved`;
                } else if (d.debriefMin >= 8) {
                    debriefDelta += 8;
                }

                if (d.plan === `observed`) { transferDelta += 10; coachKey = (d.structure === `whatso` || d.structure === `kolb`) && d.debriefMin >= 5 ? `coach_r4_plan_observed` : coachKey; }
                else if (d.plan === `self`) { transferDelta += 2; }
                else if (d.plan === `happy`) { transferDelta -= 8; ds.measuredSatisfaction = true; coachKey = `coach_r4_plan_happy`; }
                else if (d.plan === `none`) { transferDelta -= 6; }

                // Deliberate subtraction protects the debrief; refusing to cut squeezes reflection.
                if (d.cut === `objectives`) { debriefDelta += 6; transferDelta += 4; }
                else if (d.cut === `exercise`) { debriefDelta += 4; }
                else if (d.cut === `debrief`) { debriefDelta -= 12; transferDelta -= 8; ds.debriefStarved = true; coachKey = `coach_r4_cutdebrief`; }
                else if (d.cut === `nothing`) { debriefDelta -= 6; transferDelta -= 4; }

                summaryKey = ((d.structure === `whatso` || d.structure === `kolb`) && d.debriefMin >= 5 && d.plan === `observed`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with caps.
            ds.engagement = Math.max(0, Math.min(100, ds.engagement + engagementDelta));
            ds.debriefQuality = Math.max(0, Math.min(100, ds.debriefQuality + debriefDelta));

            // Transfer score is the composite bet: it can never outrun a broken design.
            // Penalties from the experiential failure modes cap the achievable transfer.
            ds.transfer = Math.max(0, Math.min(100, ds.transfer + transferDelta));
            // Engagement and debrief gate the transfer ceiling: a thrilling exercise with no
            // reflection (Kolb stops at "experience") transfers little; a disengaged half-room caps it too.
            const engGate = 0.5 + (ds.engagement / 100) * 0.5;     // 0.5 .. 1.0
            const debriefGate = 0.5 + (ds.debriefQuality / 100) * 0.5; // 0.5 .. 1.0
            const ceiling = Math.round(58 + (100 - 58) * engGate * debriefGate);
            if (ds.transfer > ceiling) ds.transfer = ceiling;

            ds.transferHistory.push(ds.transfer);
            ds.engagementHistory.push(ds.engagement);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A — expose the composite (clamped 0-100) on the reporting paths
            // (express_resolveDomainScore -> performance.overallScore / domainState.score;
            // trend -> results.score/overallScore). Same weights as getPerformanceSummary.
            var _c = Math.max(0, Math.min(100, Math.round(ds.transfer * 0.5 + ds.engagement * 0.25 + ds.debriefQuality * 0.25)));
            ds.score = _c;
            ds.performance = { overallScore: _c };
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                transfer: ds.transfer,
                transferDelta: transferDelta,
                engagement: ds.engagement,
                engagementDelta: engagementDelta,
                debriefQuality: ds.debriefQuality,
                timeUsed: ds.timeUsed,
                overrun: ds.overrun,
                debriefStarved: ds.debriefStarved,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

