        formatCompletionMessage(summary) {
            var t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            var score = (summary.score != null) ? summary.score : 0;
            var grade = summary.gradeKey ? t(summary.gradeKey) : '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            var metric = function (label, val) {
                return '<div class="lbd-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            var eur = function (v) { return '\u20ac' + Math.round((v || 0) / 1000) + 'k'; };
            var metrics = ''
                + metric(t('comp_transfer_label'), (summary.transfer != null ? summary.transfer : '-'))
                + metric(t('comp_eng_label'), (summary.engagement != null ? summary.engagement : '-'))
                + metric(t('comp_debrief_label'), (summary.debriefQuality != null ? summary.debriefQuality : '-'))
                + metric(t('comp_fee_label'), eur(summary.feeAtRisk));
            return ''
                + '<div class="lbd-completion">'
                +   '<div class="lbd-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="lbd-completion-verdict">' + grade + '</div>'
                +   '<div class="lbd-completion-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="lbd-completion-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="lbd-completion-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const transfer = ds.transfer, engagement = ds.engagement, debrief = ds.debriefQuality;

            // The renewal is won only if projected transfer clears the 70 threshold.
            const guaranteeHit = transfer >= this.TARGET;
            const renewalSafe = guaranteeHit && engagement >= 60 && debrief >= 60;
            const composite = Math.round(transfer * 0.5 + engagement * 0.25 + debrief * 0.25);

            let performance = `Lecture Redux`;
            if (renewalSafe && composite >= 74) performance = `Transfer Designer`;
            else if (guaranteeHit && composite >= 64) performance = `Guarantee Met`;
            else if (composite >= 52) performance = `Fragile Design`;

            const insights = [];
            if (renewalSafe) {
                insights.push(window.mySimulation.t(`insight_renewal`));
            } else if (guaranteeHit) {
                insights.push(window.mySimulation.t(`insight_guarantee`));
            } else {
                insights.push(window.mySimulation.t(`insight_missed`));
            }
            if (ds.revertedToTelling) insights.push(window.mySimulation.t(`insight_telling`));
            if (ds.overrun) insights.push(window.mySimulation.t(`insight_overrun`));
            if (ds.debriefStarved) insights.push(window.mySimulation.t(`insight_starved`));
            if (ds.randomCasting) insights.push(window.mySimulation.t(`insight_casting`));
            if (ds.measuredSatisfaction) insights.push(window.mySimulation.t(`insight_satisfaction`));

            const _sc = Math.max(0, Math.min(100, composite));
            const _gk = (renewalSafe && composite >= 74) ? 'grade_designer' : (guaranteeHit && composite >= 64) ? 'grade_guarantee' : (composite >= 52) ? 'grade_fragile' : 'grade_lecture';
            if (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) {
                window.mySimulation.state.domainState.score = _sc;
                window.mySimulation.state.domainState.performance = { overallScore: _sc, grade: window.mySimulation.t(_gk) };
            }
            return {
                score: _sc,
                gradeKey: _gk,
                transfer: transfer,
                engagement: engagement,
                debriefQuality: debrief,
                composite: composite,
                performance: performance,
                guaranteeHit: guaranteeHit,
                renewalSafe: renewalSafe,
                feeAtRisk: this.FEE_AT_RISK,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.revertedToTelling) return window.mySimulation.t(`hint_telling`);
            if (ds.overrun) return window.mySimulation.t(`hint_overrun`);
            if (ds.debriefStarved) return window.mySimulation.t(`hint_starved`);
            if (results.engagementDelta < -8) return window.mySimulation.t(`hint_engagement`);
            if (ds.transfer >= this.TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

